#!/usr/bin/env python3
"""Build the automatic shared-folder runtime from the verified 019.2 payload.
No console access or publication. All original runtime bytes stay pinned.
"""
from pathlib import Path
import argparse, hashlib, json, re, zipfile
ROOT=Path(__file__).resolve().parents[1]
BASE_SHA='716a1ca72360bb9835f03046c5282d2a530594bab84b9a8757b5adf235717c73'
BASE_MANIFEST='b01d6c5dd932d51f5990a5b7dcafbcf954cca03a5d4e0414cc6976594315f712'
RULE={'prefix':'FAKE78','allow_list':'/data/wine11/title-rule/blender-shared/allow-list'}
def sha(b):return hashlib.sha256(b).hexdigest()
def create(base,launcher,output):
 if output.exists():raise ValueError('Output already exists')
 if sha(base.read_bytes())!=BASE_SHA:raise ValueError('Base runtime archive differs')
 with zipfile.ZipFile(base) as z:
  raw=z.read('vapor-runtime.json')
  if sha(raw)!=BASE_MANIFEST:raise ValueError('Base manifest differs')
  m=json.loads(raw);specs=m['files']+m['title_files'];payload={};modes={}
  expected={x['path'] for x in specs}|{'vapor-runtime.json','title/vapor-compatibility.json'}
  if set(z.namelist())!=expected or len(z.namelist())!=len(expected):raise ValueError('Base inventory differs')
  for f in specs:
   b=z.read(f['path'])
   if len(b)!=f['size'] or sha(b)!=f['sha256']:raise ValueError('Base bytes differ: '+f['path'])
   payload[f['path']]=b;modes[f['path']]=f['mode']
 native=json.loads((launcher/'native-title-build.json').read_bytes());helper=json.loads((launcher/'lapy-manifest.json').read_bytes())
 if not native.get('any_title') or native.get('title_rule')!=RULE or helper.get('title_rule')!=RULE or helper.get('service') or helper.get('max_requests')!=1:raise ValueError('Expected Blender-only rule-mode helper and launcher')
 if sha((launcher/'eboot.bin').read_bytes())!=native['eboot_sha256'] or sha((launcher/'lapy.elf').read_bytes())!=helper['elf_sha256']:raise ValueError('Launcher/helper provenance differs')
 for name in ['eboot.bin','native-title-build.json','lapy.elf','lapy-manifest.json']:
  n='title/'+name;payload[n]=(launcher/name).read_bytes();modes[n]='0755' if name in ['eboot.bin','lapy.elf'] else '0644'
 m['id']='blender-019.3';m['source_receipt']='runtime-patches/blender/automatic-bridge-source-receipt.json'
 m['title_files']=[dict(path=n,size=len(payload[n]),sha256=sha(payload[n]),mode=modes[n]) for n in sorted(payload) if n.startswith('title/')]
 m['qualification']['delivery']='Automatic shared-folder setup; acceptance evidence shipped with release'
 m['qualification']['owner_confirmed']+=['shared Documents and Desktop save/reopen','Vapor launch and same-window Save As','shared Blender file recycle deletion']
 raw=(json.dumps(m,indent=2,sort_keys=True)+'\n').encode();pin=sha(raw)
 for n in ['vapor-runtime.json','title/vapor-compatibility.json']:payload[n]=raw;modes[n]='0644'
 (ROOT/'assets/blender-runtime/manifest.json').write_bytes(raw)
 order=[x['path'] for x in m['files']]+['vapor-runtime.json']+[x['path'] for x in m['title_files']]+['title/vapor-compatibility.json']
 output.parent.mkdir(parents=True,exist_ok=True)
 with zipfile.ZipFile(output,'x',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
  for n in order:
   i=zipfile.ZipInfo(n,(2026,11,16,0,0,0));i.create_system=3;i.external_attr=(0o100000|int(modes[n],8))<<16;i.compress_type=zipfile.ZIP_DEFLATED;z.writestr(i,payload[n])
 archive_pin=sha(output.read_bytes())
 p=ROOT/'tools/prepare_blender_runtime.py';s=p.read_text();s=re.sub(r"MANIFEST_SHA256 = '[0-9a-f]+'",f"MANIFEST_SHA256 = '{pin}'",s);s=re.sub(r"ARCHIVE_SHA256 = '[0-9a-f]+'",f"ARCHIVE_SHA256 = '{archive_pin}'",s);s=s.replace('blender-019.2','blender-019.3').replace('blender-runtime-v2','blender-runtime-v3');p.write_text(s)
 h=['// Generated by tools/create_blender_shared_release.py.','#pragma once','#include "runtime/package_installer.h"','namespace ww::steam_integration {',f'inline constexpr const char* kBlenderRuntimeManifestSha256 = "{pin}";']
 for group,names in [('BlenderRuntimeFiles',[n for n in order if not n.startswith('title/')]),('BlenderTitleFiles',[n for n in order if n.startswith('title/')])]:
  h+=['inline std::vector<playden::runtime::KitFile> '+group+'() { return {'];h += [f'  {{"{n}", {len(payload[n])}, "{sha(payload[n])}", {modes[n]}}},' for n in names];h+=['}; }']
 h+=['inline void ConfigureBlenderRuntime(playden::runtime::FilesystemPackageInstaller& installer, const std::filesystem::path& runtime) {',f' installer.SetGameRuntimeOverride({{365670,runtime/"compatibility/steam-365670-blender-v1","blender-019.3",kBlenderRuntimeManifestSha256,BlenderRuntimeFiles(),BlenderTitleFiles()}});','}','}']
 (ROOT/'src/steam_integration/blender_runtime_files.hpp').write_text('\n'.join(h)+'\n')
 p=ROOT/'tools/fix-vapor-install-modes.py';p.write_text(re.sub(r"BLENDER_PIN = '[0-9a-f]+'",f"BLENDER_PIN = '{pin}'",p.read_text()))
 helper_files=[f for f in m['title_files'] if f['path'] in ['title/lapy.elf','title/lapy-manifest.json']]
 rows=' ||\n      '.join('(file.path=="%s" && file.size==%d && file.sha256=="%s" && file.mode==%s)'%(f['path'],f['size'],f['sha256'],f['mode']) for f in helper_files)
 policy=['// Generated from the pinned Blender019.3 manifest.','#pragma once','namespace ww::steam_integration {',f'inline constexpr const char* kBlenderSharedReleasePin="{pin}";', 'template<class Runtime,class File>bool BlenderSharedHelperFileAllowed(const Runtime&runtime,const File&file){', ' return runtime.steam_app_id==365670 && runtime.revision=="blender-019.3" && runtime.manifest_sha256==kBlenderSharedReleasePin && (', '      '+rows+');','}','}']
 (ROOT/'src/steam_integration/blender_shared_release_policy.hpp').write_text('\n'.join(policy)+'\n')
 print('Runtime manifest',pin,'archive',archive_pin)
if __name__=='__main__':
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--base-runtime',type=Path,required=True);p.add_argument('--launcher',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();create(a.base_runtime,a.launcher,a.output)
